import pdfplumber
import json
import openpyxl

# Extract Excel data
wb = openpyxl.load_workbook('/root/employees_current.xlsx')
ws = wb.active

headers = []
for cell in ws[1]:
    if cell.value:
        headers.append(cell.value)

excel_data = {}
for row in ws.iter_rows(min_row=2, values_only=True):
    if row[0]:
        emp_id = row[0]
        emp_dict = {}
        for col_idx, header in enumerate(headers):
            emp_dict[header] = row[col_idx]
        excel_data[emp_id] = emp_dict

# Extract PDF data using pdfplumber
pdf_data = {}

with pdfplumber.open('/root/employees_backup.pdf') as pdf:
    for page_num, page in enumerate(pdf.pages):
        tables = page.extract_tables()
        if tables:
            for table in tables:
                if len(table) > 0:
                    pdf_headers = table[0]

                    for row in table[1:]:
                        if row[0] and str(row[0]).startswith('EMP'):
                            emp_id = str(row[0])
                            emp_dict = {}
                            for idx, header in enumerate(pdf_headers):
                                if idx < len(row):
                                    value = row[idx]
                                    if header == 'Salary' and value:
                                        try:
                                            value = int(str(value).replace(',', ''))
                                        except:
                                            pass
                                    elif header in ['Years', 'Score'] and value:
                                        try:
                                            value = float(value) if '.' in str(value) else int(value)
                                        except:
                                            pass
                                    emp_dict[header] = value
                            if 'ID' not in emp_dict:
                                emp_dict['ID'] = emp_id
                            pdf_data[emp_id] = emp_dict

# Find deleted employees (in PDF but not in Excel)
pdf_ids = set(pdf_data.keys())
excel_ids = set(excel_data.keys())

deleted_ids = sorted(pdf_ids - excel_ids)
modified_records = []

# Find modified employees
for emp_id in sorted(pdf_ids & excel_ids):
    pdf_record = pdf_data[emp_id]
    excel_record = excel_data[emp_id]

    for field in pdf_record:
        if field in excel_record:
            pdf_value = pdf_record[field]
            excel_value = excel_record[field]

            # Skip ID field
            if field == 'ID':
                continue

            # Compare values
            if pdf_value != excel_value:
                modified_records.append({
                    "id": emp_id,
                    "field": field,
                    "old_value": pdf_value,
                    "new_value": excel_value
                })

# Sort modified records by ID
modified_records = sorted(modified_records, key=lambda x: x['id'])

# Create the result dictionary
result = {
    "deleted_employees": deleted_ids,
    "modified_employees": modified_records
}

print(f"Deleted employees: {len(deleted_ids)}")
print(f"Modified employee records: {len(modified_records)}")
print(f"\nFirst few deleted IDs: {deleted_ids[:10]}")
print(f"\nFirst few modified records:")
for rec in modified_records[:5]:
    print(f"  {rec}")

# Write to file
with open('/root/diff_report.json', 'w') as f:
    json.dump(result, f, indent=2)

print("\nReport written to /root/diff_report.json")

